// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    HighGasReceiver receiver;

    function setUp() public {
        c = new SimpleWallet();
        receiver = new HighGasReceiver();
        vm.deal(address(c), 1 ether);
    }

    function testRegression_property() public {
        vm.prank(c.owner());
        bool success;
        try c.sendMoney(address(receiver), 1) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

contract HighGasReceiver {
    uint256 public counter;
    receive() external payable {
        for (uint256 i = 0; i < 100; i++) {
            counter++;
        }
    }
}
